package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/organizations") class OrganizationController {private final TenantService service;OrganizationController(TenantService s){service=s;}private UUID user(Authentication a){return UUID.fromString(a.getName());}@GetMapping List<OrganizationResponse> list(Authentication a){return service.organizations(user(a));}@PostMapping @ResponseStatus(HttpStatus.CREATED) OrganizationResponse create(Authentication a,@Valid @RequestBody OrganizationRequest r){return service.createOrganization(user(a),r);}}
@RestController @RequestMapping("/api/organization") class MembershipController {private final TenantService service;MembershipController(TenantService s){service=s;}private Membership member(Authentication a,String org){return service.membership(UUID.fromString(a.getName()),org);}@GetMapping("/members") List<MembershipResponse> members(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.members(member(a,org));}@PostMapping("/members") @ResponseStatus(HttpStatus.CREATED) MembershipResponse add(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody MembershipRequest r){return service.addMember(member(a,org),r);}@PutMapping("/members/{id}/role") MembershipResponse role(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody RoleUpdateRequest r){return service.updateRole(member(a,org),id,r);}}
@RestController @RequestMapping("/api/master-data") class MasterDataController {private final TenantService service;MasterDataController(TenantService s){service=s;}private Membership member(Authentication a,String org){return service.membership(UUID.fromString(a.getName()),org);}@GetMapping("/locations") List<LocationResponse> locations(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.locations(member(a,org));}@PostMapping("/locations") @ResponseStatus(HttpStatus.CREATED) LocationResponse location(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody LocationRequest r){return service.createLocation(member(a,org),r);}@GetMapping("/ingredients") List<IngredientResponse> ingredients(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.ingredients(member(a,org));}@PostMapping("/ingredients") @ResponseStatus(HttpStatus.CREATED) IngredientResponse ingredient(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody IngredientRequest r){return service.createIngredient(member(a,org),r);}@GetMapping("/suppliers") List<SupplierResponse> suppliers(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.suppliers(member(a,org));}@PostMapping("/suppliers") @ResponseStatus(HttpStatus.CREATED) SupplierResponse supplier(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody SupplierRequest r){return service.createSupplier(member(a,org),r);}@PostMapping("/suppliers/{id}/ingredients") SupplierResponse link(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody SupplierIngredientRequest r){return service.linkIngredient(member(a,org),id,r);}}
@RestController @RequestMapping("/api/organization/invites") class InvitationController {private final InvitationService invites;private final TenantService tenants;InvitationController(InvitationService i,TenantService t){invites=i;tenants=t;}@PostMapping @ResponseStatus(HttpStatus.CREATED) InvitationResponse create(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody InvitationRequest r){return invites.create(tenants.membership(UUID.fromString(a.getName()),org),r);}}
